function collideCircle(p, r){
  for (const b of colliders){
    const cx = Math.max(b.x0, Math.min(p.x, b.x1));
    const cz = Math.max(b.z0, Math.min(p.z, b.z1));
    let dx = p.x-cx, dz = p.z-cz; const d2 = dx*dx+dz*dz;
    if (d2 > r*r) continue;
    if (d2 > 1e-9) { const d=Math.sqrt(d2); p.x = cx+dx/d*r; p.z = cz+dz/d*r; }
    else {
      const l=p.x-b.x0, ri=b.x1-p.x, t=p.z-b.z0, bt=b.z1-p.z, m=Math.min(l,ri,t,bt);
      if (m===l) p.x=b.x0-r; else if(m===ri) p.x=b.x1+r; else if(m===t) p.z=b.z0-r; else p.z=b.z1+r;
    }
  }
  for (const t of treeCols){
    const dx=p.x-t.x, dz=p.z-t.z, rr=r+t.r, d2=dx*dx+dz*dz;
    if (d2 < rr*rr && d2>1e-9){ const d=Math.sqrt(d2); p.x=t.x+dx/d*rr; p.z=t.z+dz/d*rr; }
  }
}

function updatePlayer(dt){
  const sp = (keys['ShiftLeft']||keys['ShiftRight']) ? 7.2 : 4.4;
  let fx=0, fz=0;
  if (keys['KeyW']) fz -= 1; if (keys['KeyS']) fz += 1;
  if (keys['KeyA']) fx -= 1; if (keys['KeyD']) fx += 1;
  const moving = fx||fz;
  if (moving){
    const l = Math.hypot(fx,fz); fx/=l; fz/=l;
    const sin=Math.sin(player.yaw), cos=Math.cos(player.yaw);
    const wx = fx*cos - fz*sin, wz = fx*sin + fz*cos;
    const p = {x:player.x + wx*sp*dt, z:player.z + wz*sp*dt};
    collideCircle(p, .38);
    player.x = p.x; player.z = p.z;
    stepTimer += sp*dt;
    if (stepTimer > 2.3){ stepTimer = 0; playStep(); }
  }
  // lompat & gravitasi
  if (keys['Space'] && player.onGround){ player.vy = 4.6; player.onGround=false; }
  player.vy -= 13*dt; player.y += player.vy*dt;
  if (player.y <= 0){ player.y=0; player.vy=0; player.onGround=true; }
  player.x = Math.max(-310, Math.min(310, player.x));
  player.z = Math.max(-310, Math.min(310, player.z));
  camera.position.set(player.x, player.y + 1.62 + (moving?Math.sin(stepTimer*2.7)*.035:0), player.z);
  camera.rotation.set(player.pitch, player.yaw, 0);
}
let stepTimer = 0;

// bobbing kepala saat di dalam mobil
const carLook = { yaw:0, pitch:0 };

// ============================================================
// 7. DRIVING
// ============================================================
let driving = false;
function enterCar(){
  if (carrying){ showToast('Tanganmu penuh', 'Taruh / pasang dulu (Q untuk taruh)'); return; }
  const missing = missingParts();
  if (missing){ showToast('Mobil belum lengkap', 'Kurang: '+missing.join(', ')); return; }
  if (car.fuel < 5){ showToast('Bahan bakar habis', 'Isi pakai jerigen'); return; }
  driving = true; carLook.yaw=0; carLook.pitch=0;
  camera.position.set(-.4,1.28,-.05); camera.rotation.set(0,0,0);
  carGroup.add(camera);
  document.getElementById('dash').style.display='block';
  refreshTasks();
}
function exitCar(){
  if (!driving) return;
  if (Math.abs(car.v) > 3){ showToast('Terlalu cepat untuk turun!', 'Rem dulu (S)'); return; }
  car.v = 0; driving=false; car.engineOn=false;
  carGroup.remove(camera);
  player.x = car.x + Math.sin(car.rot+Math.PI/2)*1.4; player.z = car.z + Math.cos(car.rot+Math.PI/2)*1.4;
  player.y = 0;
  camera.position.set(player.x, 1.62, player.z);
  document.getElementById('dash').style.display='none';
}
function missingParts(){
  const need = ['engine','gearbox','radiator','battery','hood'];
  const miss = need.filter(n=>!car.installed.has(n));
  const wheels = [...car.installed].filter(i=>i.startsWith('wheel')).length;
  if (wheels<4) miss.push((4-wheels)+' roda');
  return miss;
}
function toggleIgnition(){
  if (car.engineOn){ car.engineOn=false; showToast('Mesin mati'); return; }
  const miss = missingParts();
  if (miss.length){ showToast('Tidak bisa dinyalakan', 'Kurang: '+miss.join(', ')); return; }
  if (car.fuel <= 0){ showToast('Bensin habis', 'Cari jerigen!'); return; }
  showToast('Dinyalakan...', 'Starter berputar'); 
  crank(1.4, ()=>{
    if (batteryCharge<=0){ showToast('Aki soak', 'Cas aki dulu di meja kerja'); return; }
    if (car.fuel<=0){ showToast('Bensin habis'); return; }
    car.engineOn = true; markTask('start');
    showToast('◉ Mesin hidup!', 'W/S gas · A/D setir · F keluar');
  });
}
function updateCar(dt){
  const thr = keys['KeyW']?1:0, brk = keys['KeyS']?1:0;
  const steerIn = (keys['KeyA']?1:0) - (keys['KeyD']?1:0);
  if (car.engineOn){
    if (thr) car.v += 7.5*dt * (car.v<0?1.6:1);
    if (brk){
      if (car.v > .3) car.v -= 10*dt;
      else car.v -= 3.2*dt;                    // mundur
    }
    car.v = Math.max(-6, Math.min(36, car.v));
    car.fuel -= (0.02 + Math.abs(car.v)*0.004*(0.5+thr)) * dt;
    if (car.fuel <= 0){ car.fuel=0; car.engineOn=false; showToast('Bensin habis!','Hanya jalan kaki pulang...'); }
  }
  if (!thr && !brk) car.v *= (1 - 1.1*dt);
  if (keys['Space']) car.v *= (1 - 3.5*dt);
  if (!car.engineOn && Math.abs(car.v)<.05) car.v = 0;
  const steerTarget = steerIn * .58 / (1 + Math.abs(car.v)*.06);
  car.steer += (steerTarget - car.steer) * Math.min(1, 8*dt);
  if (Math.abs(car.v) > .1){
    car.rot += (car.v/2.5) * Math.tan(car.steer) * dt * (car.v<0?-1:1) * (car.v<0?-1:1);
    // ^ mundur: kemudi terbalik terasa benar
  }
  // gerak
  const nx = car.x + Math.sin(car.rot)*car.v*dt;
  const nz = car.z + Math.cos(car.rot)*car.v*dt;
  // tabrakan: 2 lingkaran (depan/belakang)
  for (const off of [1.35,-1.35]){
    const p = { x: nx + Math.sin(car.rot)*off, z: nz + Math.cos(car.rot)*off };
    const before = {x:p.x, z:p.z};
    collideCircle(p, 1.0);
    if (Math.hypot(p.x-before.x,p.z-before.z) > .001){
      if (Math.abs(car.v) > 7){ damageFlash(); playClunk(60,.3,.7); }
      car.v *= -.25;
      car.x = p.x - Math.sin(car.rot)*off; car.z = p.z - Math.cos(car.rot)*off;
      updateCarTransform(); return;
    }
  }
  car.x = Math.max(-300,Math.min(300,nx)); car.z = Math.max(-300,Math.min(300,nz));
  car.wheelSpin += car.v/CAR.wheelR*dt;
  // rpm/gear (otomatis 4-percepatan)
  const kmh = Math.abs(car.v)*3.6;
  const gears = [0,14,32,55,999];
  let g2 = 1; for (let i=1;i<5;i++) if (kmh>=gears[i-1] && kmh<gears[i]) { g2=i; break; }
  car.gear = g2;
  const lo = gears[g2-1], hi = gears[g2]===999?95:gears[g2];
  const band = Math.max(0,(kmh-lo))/(Math.max(hi-lo,14));
  car.rpm = car.engineOn ? (900 + band*6100 + thr*300) : 0;
  // visual
  updateCarTransform();
  if (wheelMeshes[0]) for (let i=0;i<4;i++){
    const w = wheelMeshes[i]; if (!w) continue;
    w.children[0] && (w.children[0].rotation.x = car.wheelSpin);
    if (i<2) w.rotation.y = car.steer;
  }
  steeringWheel.rotation.z = -car.steer*4.2;
  // sampai kauppa?
  if (Math.hypot(car.x-STORE.x, car.z-STORE.z) < 15 && !winShown){
    winShown = true; markTask('store');
    showToast('★ SAMPAI KAUPPA! ★', 'Kau menyelesaikan musim panasmu. Mobil hidup, jalan terbuka.');
    playClunk(300,.4,.5); setTimeout(()=>playClunk(400,.4,.5),180); setTimeout(()=>playClunk(520,.5,.5),360);
  }
}
function updateCarTransform(){
  carGroup.position.set(car.x, 0, car.z);
  carGroup.rotation.y = car.rot;
  // bob & roll ringan
  carGroup.rotation.z = -car.steer * Math.abs(car.v) * .006;
  carGroup.rotation.x = Math.max(-.03, Math.min(.03, -(keys['KeyW']?1:0)*Math.abs(car.v)*.0022 + (keys['KeyS']?1:0)*Math.abs(car.v)*.0022)));
}
let winShown = false;

// ============================================================
// 8. INTERAKSI (raycast tengah layar)
// ============================================================
const interactRoots = [];
parts.forEach(p=> interactRoots.push(p.group));
interactRoots.push(jerrycan.group, keyItem.group, shell, chassis, interior, chargerSlot);

const raycaster = new THREE.Raycaster();
raycaster.far = 3.4;
let hoverIid = null;

function iidFrom(obj){
  while (obj){
    if (obj === shell || (obj.parent===carGroup && obj!==chassis)) return 'car';
    if (obj === chargerSlot) return 'charger';
    if (obj.userData && obj.userData.part) return obj.userData.part;
    obj = obj.parent;
  }
  return null;
}
function updateHover(){
  raycaster.setFromCamera({x:0,y:0}, camera);
  const hits = raycaster.intersectObjects(interactRoots, true);
  let iid = null;
  for (const h of hits){
    if (driving) break;
    const id = iidFrom(h.object);
    if (!id) continue;
    if (id.startsWith('wheel') && partById(id).state!=='loose') continue;
    if (id==='car' && carrying && !carrying.startsWith('wheel')) { iid='car'; break; }
    if (id==='car' && !carrying){ iid='car'; break; }
    if (id!=='car'){ iid=id; break; }
  }
  hoverIid = iid;
  const ch = document.getElementById('crosshair');
  ch.classList.toggle('hit', !!iid);
  const hint = document.getElementById('hint');
  const txt = hintText(iid);
  if (txt){ hint.style.display='block'; hint.innerHTML = txt; }
  else hint.style.display='none';
}
function hintText(iid){
  if (!iid || driving) return null;
  if (iid==='keys' && keyItem.state==='loose') return '<b>[E]</b> Ambil kunci kontak';
  if (iid==='charger'){
    if (carrying==='battery' && batteryCharge<100) return '<b>[E]</b> Taruh aki di charger <span class="sub">Cas sampai penuh (~6 dtk)</span>';
    if (!carrying && chargerBattery && batteryCharge>=100) return '<b>[E]</b> Ambil aki (penuh)';
    if (!carrying && chargerBattery) return 'Aki sedang dicas... <span class="sub">'+Math.round(batteryCharge)+'%</span>';
    return null;
  }
  if (iid==='jerrycan' && jerrycan.state==='loose') return '<b>[E]</b> Ambil jerigen bensin';
  const p = partById(iid);
  if (p && p.state==='loose'){
    const extra = iid==='battery' && batteryCharge<100 ? ' <span class="sub">masih kosong — cas dulu</span>' : '';
    return `<b>[E]</b> Ambil ${PART_LABEL[iid]}${extra}`;
  }
  if (iid==='car'){
    if (carrying==='jerrycan') return '<b>[E]</b> Isi bensin dari jerigen <span class="sub">'+jerrycan.fuel+' L</span>';
    if (carrying==='keys') return 'Kunci dipasang saat starter nanti';
    if (carrying && carrying.startsWith('wheel')) { const w=[...car.installed].filter(i=>i.startsWith('wheel')).length; return `<b>[E]</b> Pasang roda (${w}/4)`; }
    if (carrying==='battery') return batteryCharge<100
      ? 'Aki masih kosong <span class="sub">cas di meja kerja (charger kuning)</span>'
      : '<b>[E]</b> Pasang aki';
    if (carrying) return '<b>[E]</b> Pasang '+PART_LABEL[carrying];
    const miss = missingParts();
    if (miss.length) return 'Amppa 80 — kurang: '+miss.join(', ');
    if (car.fuel<5) return 'Bahan bakar habis <span class="sub">cari jerigen</span>';
    return '<b>[E]</b> Masuk & duduk <span class="sub">lalu [E] lagi untuk starter</span>';
  }
  return null;
}
let busy = 0; // kunci interaksi sementara (menuang bensin)
function tryInteract(){
  if (!started || busy>0) return;
  if (driving){ toggleIgnition(); return; }
  const iid = hoverIid;
  if (!iid) return;
  if (iid==='keys'){ if(pickupPart('keys')){ markTask('keys'); playClunk(180,.12,.3); refreshHand(); } return; }
  if (iid==='jerrycan'){ if(pickupPart('jerrycan')){ playClunk(160,.12,.3); refreshHand(); } return; }
  if (iid==='charger'){
    if (carrying==='battery'){
      const b = partById('battery');
      camera.remove(b.group); b.group.scale.setScalar(1);
      chargerSlot.add(b.group); b.group.position.set(0,.05,.15); b.group.rotation.set(0,0,0);
      b.state='charging'; charging=true; carrying=null; refreshHand();
      showToast('Aki dicas...', 'Tunggu sampai penuh');
    } else if (!carrying && chargerBattery){
      const b = partById('battery');
      if (batteryCharge>=100){ chargerSlot.remove(b.group); pickupPart('battery'); b.group.position.set(...carryTransform('battery').pos); playClunk(200,.1,.3); }
      else showToast('Aki baru '+Math.round(batteryCharge)+'%', 'Sabar...');
    }
    return;
  }
  const p = partById(iid);
  if (p && p.state==='loose' && !carrying){
    if (pickupPart(iid)){ playClunk(140,.12,.3); refreshHand(); }
    return;
  }
  if (iid==='car'){
    if (carrying==='jerrycan'){
      busy = 2.4; showToast('Menyemplung bensin...', 'gluk gluk gluk');
      playPour();
      const t0 = performance.now();
      const iv = setInterval(()=>{
        const k = (performance.now()-t0)/2400;
        if (k>=1 || !carrying){
          clearInterval(iv); busy=0;
          if (carrying==='jerrycan'){
            car.fuel = Math.min(100, car.fuel + jerrycan.fuel);
            jerrycan.fuel = Math.max(0, jerrycan.fuel - (100-car.fuel>=45?45:car.fuel));
            showToast('Tangki: '+Math.round(car.fuel)+'%');
            markTask('fuel');
            dropCarried(); jerrycan.fuel = 0;
            if (car.fuel>=100){ showToast('Tangki penuh'); }
            refreshHand();
          }
        }
      }, 100);
      return;
    }
    if (carrying && carrying!=='keys'){
      const res = installPart(carrying);
      if (res===true){
        const obj = carrying.startsWith('wheel') ? partById(carrying) : partById(carrying);
        obj.state='installed'; carrying=null; refreshHand();
        playClunk(110,.2,.5);
        markTask(carryingTaskName(obj.id));
        showToast(PART_LABEL[obj.id]+' terpasang!');
      } else if (res==='needcharge'){
        showToast('Aki masih kosong!', 'Cas dulu di meja kerja');
      }
      return;
    }
    if (!carrying){
      const miss = missingParts();
      if (!miss.length && car.fuel>=5) enterCar();
      else if (miss.length) showToast('Mobil belum lengkap', 'Kurang: '+miss.join(', '));
      else showToast('Bensin habis', 'Butuh jerigen');
    }
  }
}
function carryingTaskName(id){
  if (id==='engine') return 'engine';
  if (id==='gearbox') return 'gearbox';
  if (id==='radiator') return 'radiator';
  if (id==='battery') return 'battery';
  if (id==='hood') return 'hood';
  if (id && id.startsWith('wheel')) return 'wheels';
  return null;
}
let charging = false, chargerBattery = false;
function updateCharging(dt){
  if (!charging) return;
  batteryCharge = Math.min(100, batteryCharge + 100*dt/6);
  if (batteryCharge>=100){
    charging=false; chargerBattery=true;
    const b = partById('battery');
    showToast('Aki penuh!', '[E] di meja kerja untuk mengambil');
    playClunk(500,.2,.4);
  }
}

function refreshHand(){
  const el = document.getElementById('handItem');
  if (carrying){
    el.style.display='block';
    let extra='';
    if (carrying==='jerrycan') extra = ' · '+jerrycan.fuel+' L';
    if (carrying==='battery') extra = ' · '+Math.round(batteryCharge)+'%';
    el.innerHTML = '🤲 <b>'+PART_LABEL[carrying]+'</b>'+extra+'<br><span style="font-size:11px;color:#8fa0aa">[E] pasang di mobil · [Q] taruh</span>';
  } else el.style.display='none';
}

