    g.fillRect(0,p*plank,s,plank);
    g.globalAlpha=.3; g.fillStyle='#4e4131'; g.fillRect(0,p*plank,s,3);
    g.globalAlpha=1;
    g.strokeStyle='rgba(40,32,22,.7)'; g.lineWidth=2;
