input.content:
import { createRequire } from 'node:module'
const runtime = '/home/runner/.local/share/omgithub-playwright'
const require = createRequire(runtime + '/package.json')
const { chromium } = require('playwright')
import { readFileSync } from 'node:fs'
const config = JSON.parse(readFileSync(runtime + '/linux.json', 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(runtime + '/display', 'utf8').trim()

const url = process.argv[2]
const out = process.argv[3] || '/tmp/opencode/shot.jpg'
const driveMs = parseInt(process.argv[4] || '3000')
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1280, height: 760 } })
const errors = []
page.on('pageerror', e => errors.push(e.message))
await page.goto(url, { waitUntil: 'load', timeout: 45000 })
await page.waitForTimeout(1200)
try { await page.click('#startBtn', { timeout: 5000 }) } catch (e) { errors.push('click: ' + e.message) }
// tahan W untuk gas
await page.keyboard.down('KeyW')
await page.waitForTimeout(driveMs)
