// End-to-end gameplay test tanpa dev: kunci -> pasang semua -> cas aki -> bensin -> starter -> jalan -> kauppa
import { createRequire } from 'node:module'
const runtime = '/home/runner/.local/share/omgithub-playwright'
const require = createRequire(runtime + '/package.json')
const { chromium } = require('playwright')
import { readFileSync } from 'node:fs'
const config = JSON.parse(readFileSync(runtime + '/linux.json', 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(runtime + '/display', 'utf8').trim()

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1280, height: 760 } })
const errors = []
page.on('pageerror', e => errors.push('PAGEERR: ' + e.message))
await page.goto('http://localhost:3002/index.html?dbg=1', { waitUntil: 'load' })
await page.waitForTimeout(1000)
await page.click('#startBtn')
await page.waitForTimeout(800)

const g = () => page.evaluate('window.__dbg()')
const t = (expr) => page.evaluate(`window.__t.${expr}`)
const step = async (name, fn) => {
  try { await fn() } catch (e) { errors.push(name + ': ' + e.message) }
  await page.waitForTimeout(150)
}

// 1. ambil kunci
await step('keys', () => t("pick('keys')"))
// 2. pasang bagian besar
for (const p of ['engine','gearbox','radiator','hood']) {
  await step('pick '+p, () => t(`pick('${p}')`))
  await step('install '+p, () => t("pick('car')"))
}
// 3. cas aki
await step('pick battery', () => t("pick('battery')"))
await step('place on charger', () => t("pick('charger')"))
for (let i=0;i<8;i++) await t('charge(15)')
await page.waitForTimeout(400)
await step('take battery', () => t("pick('charger')"))
await step('install battery', () => t("pick('car')"))
// 4. roda x4
for (let i=0;i<4;i++) {
  await step('pick wheel'+i, () => t(`pick('wheel${i}')`))
  await step('install wheel'+i, () => t("pick('car')"))
}
// 5. jerigen
await step('pick jerrycan', () => t("pick('jerrycan')"))
await step('pour', () => t("pick('car')"))
await page.waitForTimeout(2700)
// 6. masuk & starter
await step('enter', () => t('enter()'))
await step('ignition', () => t('ign()'))
await page.waitForTimeout(2200)
const s1 = await g()
console.log('AFTER START:', JSON.stringify({engineOn:s1.engineOn, driving:s1.driving, fuel:s1.fuel, tasks:s1.taskState, toast:s1.toast}))
// 7. jalan
await page.keyboard.down('KeyW')
await page.waitForTimeout(3000)
await page.keyboard.up('KeyW')
const s2 = await g()
console.log('AFTER DRIVE:', JSON.stringify({pos:s2.carPos, speed:s2.speed, fuel:s2.fuel}))
// 8. ke kauppa
await step('teleport near store', () => t('place([104,164,0])'))
await page.keyboard.down('KeyW')
await page.waitForTimeout(2500)
await page.keyboard.up('KeyW')
const s3 = await g()
console.log('AT STORE:', JSON.stringify({pos:s3.carPos, speed:s3.speed, store:s3.taskState.store, toast:s3.toast}))
// 9. keluar mobil
await page.keyboard.down('KeyS'); await page.waitForTimeout(1200); await page.keyboard.up('KeyS')
await step('exit', () => t('exit()'))
const s4 = await g()
console.log('EXITED:', JSON.stringify({driving:s4.driving, cam:s4.cam, parent:s4.parent}))
console.log('ERRORS:', errors.length ? errors.join(' || ') : 'none')
await browser.close()

